UPDATE tramites
SET 
  guia = '{
    "que_es": "Es una ayuda del SEPE para personas que se quedan en paro pero NO han cotizado los 360 días mínimos para tener derecho al paro normal. Solo necesitas haber trabajado al menos 90 días (3 meses).",
    "requisitos": [
      "Estar en paro (situación legal de desempleo) y no tener derecho a la prestación contributiva (el paro normal).",
      "Haber cotizado al menos 90 días (3 meses) y menos de 360 días.",
      "No superar el límite de ingresos (el 75% del SMI, unos 915€ al mes en 2026, o menos si tienes cargas familiares).",
      "Estar inscrito como demandante de empleo y firmar el acuerdo de actividad.",
      "Presentar la solicitud dentro de los 6 meses siguientes a quedarte en paro."
    ],
    "plazos": "Tienes 6 meses desde que te quedaste en paro para pedirlo. Si lo pides en los primeros 15 días, cobras desde el día siguiente. Si tardas más, cobras desde que lo pides (pierdes días).",
    "consejos": "Si has trabajado menos de 6 meses (180 días), el subsidio dura lo mismo que lo que hayas cotizado (3, 4 o 5 meses). Si tienes hijos o familiares a cargo y has cotizado 180 días o más, puedes cobrar hasta 21 meses. Se puede cobrar aunque estés trabajando a tiempo parcial (si la suma de jornadas no llega a una completa).",
    "como_solicitar": "1. Pide cita previa en el SEPE (por internet o por teléfono).\n2. Reúne los papeles: DNI, vida laboral, certificado de empresa, y declaración de rentas (si tienes cargas familiares).\n3. Ve a tu oficina del SEPE con cita. Allí rellenas la solicitud y presentas los papeles.\n4. También puedes hacerlo online en la Sede Electrónica del SEPE si tienes Cl@ve o certificado digital."
  }'::json,
  guia_html = '<h3>¿En qué consiste?</h3><p>Es una ayuda del SEPE para personas que se quedan en paro pero NO han cotizado los 360 días mínimos para tener derecho al paro normal. Solo necesitas haber trabajado al menos 90 días (3 meses).</p><h3>Requisitos principales</h3><ul><li>Estar en paro (situación legal de desempleo) y no tener derecho a la prestación contributiva (el paro normal).</li><li>Haber cotizado al menos 90 días (3 meses) y menos de 360 días.</li><li>No superar el límite de ingresos (el 75% del SMI, unos 915€ al mes en 2026, o menos si tienes cargas familiares).</li><li>Estar inscrito como demandante de empleo y firmar el acuerdo de actividad.</li><li>Presentar la solicitud dentro de los 6 meses siguientes a quedarte en paro.</li></ul><h3>Plazos</h3><p>Tienes 6 meses desde que te quedaste en paro para pedirlo. Si lo pides en los primeros 15 días, cobras desde el día siguiente. Si tardas más, cobras desde que lo pides (pierdes días).</p><h3>Consejos y avisos importantes</h3><p>Si has trabajado menos de 6 meses (180 días), el subsidio dura lo mismo que lo que hayas cotizado (3, 4 o 5 meses). Si tienes hijos o familiares a cargo y has cotizado 180 días o más, puedes cobrar hasta 21 meses. Se puede cobrar aunque estés trabajando a tiempo parcial (si la suma de jornadas no llega a una completa).</p><h3>Cómo solicitarlo paso a paso</h3><p>1. Pide cita previa en el SEPE (por internet o por teléfono).<br>2. Reúne los papeles: DNI, vida laboral, certificado de empresa, y declaración de rentas (si tienes cargas familiares).<br>3. Ve a tu oficina del SEPE con cita. Allí rellenas la solicitud y presentas los papeles.<br>4. También puedes hacerlo online en la Sede Electrónica del SEPE si tienes Cl@ve o certificado digital.</p>'
WHERE slug = 'subsidio-cotizacion-insuficiente';
